-- INVERSE of migrations/campaign/guardswitch_the_retired_guard_knobs_say_so.sql
-- The three labels and descriptions exactly as they read before GUARD-SWITCH, captured
-- from the live main database on 2026-09-19.
update platform.feature_knob set label = 'Guard: platform.associations columns and triggers', description = 'Read by the new code inside platform.validate_edge_payload() and platform.trg_reachability_on_association(), and by any policy over the columns this campaign adds to platform.associations. OFF means the old body runs unchanged. platform.associations carries 33,808 rows and thirteen user triggers and is in the supabase_realtime publication.' where feature = 'custom' and key = 'associations_guard';
update platform.feature_knob set label = 'Guard: the custom_fields column on a standard Entity table', description = 'Read by everything that WRITES or INTERPRETS the campaign''s custom_fields column. Note what this knob cannot do: a COLUMN cannot be hidden by a flag. 63 tables sit in the supabase_realtime publication and Realtime ships whole rows, and PostgREST select(''*'') returns a new column the instant it lands — so the lane that adds it must NAME the table it is added to and state that the column is visible, and only its meaning is OFF.' where feature = 'custom' and key = 'entity_custom_fields_guard';
update platform.feature_knob set label = 'Guard: history.row_versions.row_data', description = 'Read by the writer that would store a version without its row_data. OFF means every version is written exactly as it is today. history.row_versions holds 1,275,409 rows and row_data is NOT NULL; dropping that NOT NULL is not additive and is not covered by this knob — the knob covers the WRITER, and the constraint change is its own migration with its own inverse.' where feature = 'custom' and key = 'row_versions_guard';
